import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry convtrans2d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .s32 N,
    .param .s32 Cin,
    .param .s32 Cout,
    .param .s32 H,
    .param .s32 W,
    .param .s32 kH,
    .param .s32 kW,
    .param .s32 stride_h,
    .param .s32 stride_w,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .s32 dil_h,
    .param .s32 dil_w,
    .param .s32 groups,
    .param .s32 Ho,
    .param .s32 Wo,
    .param .s32 has_bias
)
{
    .reg .pred  %p<12>;
    .reg .b64   %rd<20>;
    // Float registers
    .reg .f32   %fAcc, %f1, %f2, %f3;
    // 32-bit integer registers (signed)
    .reg .s32 %rN, %rCin, %rCout, %rH, %rW, %rKH, %rKW, %rStrideH, %rStrideW, %rPadH, %rPadW, %rDilH, %rDilW, %rGroups, %rHo, %rWo, %rHasBias;
    .reg .s32 %rTid, %rTotal, %rWoIdx, %rQ0, %rHoIdx, %rQ1, %rCoIdx, %rNIdx, %rCoutPerG, %rCinPerG, %rG, %rTmp0, %rCoRel, %rCiStart, %rCiEnd, %rCi, %rKh, %rTmp1, %rTh, %rQh, %rTmp2, %rRemH, %rKw, %rTmp3, %rTw, %rQw, %rTmp4, %rRemW, %rTmp5, %rXIndex, %rTmp6, %rWIndex, %rTmp7, %rYIndex;
    // Thread/block coordinates
    .reg .u32 %tid_x_u32, %ntid_x_u32, %ctaid_x_u32;
    .reg .s32 %tid_x_s32, %ntid_x_s32, %ctaid_x_s32;
    // Load parameters
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    ld.param.s32 %rN,       [N];
    ld.param.s32 %rCin,     [Cin];
    ld.param.s32 %rCout,    [Cout];
    ld.param.s32 %rH,       [H];
    ld.param.s32 %rW,       [W];
    ld.param.s32 %rKH,      [kH];
    ld.param.s32 %rKW,      [kW];
    ld.param.s32 %rStrideH, [stride_h];
    ld.param.s32 %rStrideW, [stride_w];
    ld.param.s32 %rPadH,    [pad_h];
    ld.param.s32 %rPadW,    [pad_w];
    ld.param.s32 %rDilH,    [dil_h];
    ld.param.s32 %rDilW,    [dil_w];
    ld.param.s32 %rGroups,  [groups];
    ld.param.s32 %rHo,      [Ho];
    ld.param.s32 %rWo,      [Wo];
    ld.param.s32 %rHasBias, [has_bias];
    // Compute global linear thread id
    mov.u32     %tid_x_u32,   %tid.x;
    mov.u32     %ntid_x_u32,  %ntid.x;
    mov.u32     %ctaid_x_u32, %ctaid.x;
    cvt.s32.u32 %tid_x_s32,   %tid_x_u32;
    cvt.s32.u32 %ntid_x_s32,  %ntid_x_u32;
    cvt.s32.u32 %ctaid_x_s32, %ctaid_x_u32;
    mad.lo.s32  %rTid, %ctaid_x_s32, %ntid_x_s32, %tid_x_s32;    // rTid = blockIdx.x * blockDim.x + threadIdx.x
    // total_elems = N * Cout * Ho * Wo
    mul.lo.s32 %rTmp0, %rN, %rCout;
    mul.lo.s32 %rTmp1, %rTmp0, %rHo;
    mul.lo.s32 %rTotal, %rTmp1, %rWo;
    setp.ge.s32 %p0, %rTid, %rTotal;
    @%p0 bra EXIT;
    // Decode indices from rTid: [n, co, ho, wo] with order Wo->Ho->Cout->N
    // wo = rTid % Wo
    rem.s32 %rWoIdx, %rTid, %rWo;
    // q = rTid / Wo
    div.s32 %rQ0, %rTid, %rWo;
    // ho = q % Ho
    rem.s32 %rHoIdx, %rQ0, %rHo;
    // q = q / Ho
    div.s32 %rQ1, %rQ0, %rHo;
    // co = q % Cout
    rem.s32 %rCoIdx, %rQ1, %rCout;
    // n = q / Cout
    div.s32 %rNIdx, %rQ1, %rCout;
    // Group computations
    div.s32 %rCoutPerG, %rCout, %rGroups;
    div.s32 %rCinPerG, %rCin, %rGroups;
    // g = co / CoutPerG
    div.s32 %rG, %rCoIdx, %rCoutPerG;
    // co_rel = co - g*CoutPerG
    mul.lo.s32 %rTmp0, %rG, %rCoutPerG;
    sub.s32 %rCoRel, %rCoIdx, %rTmp0;
    // ci_start = g*CinPerG; ci_end = ci_start + CinPerG
    mul.lo.s32 %rCiStart, %rG, %rCinPerG;
    add.s32 %rCiEnd, %rCiStart, %rCinPerG;
    // Accumulator
    mov.f32 %fAcc, 0f00000000;
    // ci loop
    mov.s32 %rCi, %rCiStart;
CI_LOOP:
    setp.ge.s32 %p1, %rCi, %rCiEnd;
    @%p1 bra AFTER_CI;
    // kh loop
    mov.s32 %rKh, 0;
KH_LOOP:
    setp.ge.s32 %p2, %rKh, %rKH;
    @%p2 bra NEXT_CI;
    // t_h = ho + pad_h - kh * dil_h
    mul.lo.s32 %rTmp1, %rKh, %rDilH;
    add.s32 %rTh, %rHoIdx, %rPadH;
    sub.s32 %rTh, %rTh, %rTmp1;
    // qh = t_h / stride_h; remh = t_h - qh*stride_h
    div.s32 %rQh, %rTh, %rStrideH;
    mul.lo.s32 %rTmp2, %rQh, %rStrideH;
    sub.s32 %rRemH, %rTh, %rTmp2;
    setp.ne.s32 %p3, %rRemH, 0;
    @%p3 bra NEXT_KH;
    setp.lt.s32 %p4, %rQh, 0;
    @%p4 bra NEXT_KH;
    setp.ge.s32 %p5, %rQh, %rH;
    @%p5 bra NEXT_KH;
    // kw loop
    mov.s32 %rKw, 0;
KW_LOOP:
    setp.ge.s32 %p6, %rKw, %rKW;
    @%p6 bra NEXT_KH;
    // t_w = wo + pad_w - kw * dil_w
    mul.lo.s32 %rTmp3, %rKw, %rDilW;
    add.s32 %rTw, %rWoIdx, %rPadW;
    sub.s32 %rTw, %rTw, %rTmp3;
    // qw = t_w / stride_w; remw = t_w - qw*stride_w
    div.s32 %rQw, %rTw, %rStrideW;
    mul.lo.s32 %rTmp4, %rQw, %rStrideW;
    sub.s32 %rRemW, %rTw, %rTmp4;
    setp.ne.s32 %p7, %rRemW, 0;
    @%p7 bra INC_KW;
    setp.lt.s32 %p8, %rQw, 0;
    @%p8 bra INC_KW;
    setp.ge.s32 %p9, %rQw, %rW;
    @%p9 bra INC_KW;
    // x_index = (((n*Cin + ci)*H + qh)*W + qw)
    mul.lo.s32 %rTmp5, %rNIdx, %rCin;
    add.s32 %rTmp5, %rTmp5, %rCi;         // n*Cin + ci
    mul.lo.s32 %rTmp5, %rTmp5, %rH;
    add.s32 %rTmp5, %rTmp5, %rQh;
    mul.lo.s32 %rTmp5, %rTmp5, %rW;
    add.s32 %rXIndex, %rTmp5, %rQw;
    // w_index = ((((ci)*CoutPerG + co_rel)*kH + kh)*kW + kw)
    mul.lo.s32 %rTmp6, %rCi, %rCoutPerG;
    add.s32 %rTmp6, %rTmp6, %rCoRel;
    mul.lo.s32 %rTmp6, %rTmp6, %rKH;
    add.s32 %rTmp6, %rTmp6, %rKh;
    mul.lo.s32 %rTmp6, %rTmp6, %rKW;
    add.s32 %rWIndex, %rTmp6, %rKw;
    // Load x and w
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    mul.wide.s32 %rd7, %rWIndex, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];
    // acc += x * w
    fma.rn.f32 %fAcc, %f1, %f2, %fAcc;
INC_KW:
    add.s32 %rKw, %rKw, 1;
    bra KW_LOOP;
NEXT_KH:
    add.s32 %rKh, %rKh, 1;
    bra KH_LOOP;
NEXT_CI:
    add.s32 %rCi, %rCi, 1;
    bra CI_LOOP;
AFTER_CI:
    // Add bias if requested
    setp.eq.s32 %p10, %rHasBias, 0;
    @%p10 bra NO_BIAS;
    mul.wide.s32 %rd9, %rCoIdx, 4;
    add.s64 %rd10, %rd3, %rd9;
    ld.global.f32 %f3, [%rd10];
    add.f32 %fAcc, %fAcc, %f3;
NO_BIAS:
    // Store to y: y_index = (((n*Cout + co)*Ho + ho)*Wo + wo)
    mul.lo.s32 %rTmp7, %rNIdx, %rCout;
    add.s32 %rTmp7, %rTmp7, %rCoIdx;
    mul.lo.s32 %rTmp7, %rTmp7, %rHo;
    add.s32 %rTmp7, %rTmp7, %rHoIdx;
    mul.lo.s32 %rTmp7, %rTmp7, %rWo;
    add.s32 %rYIndex, %rTmp7, %rWoIdx;
    mul.wide.s32 %rd11, %rYIndex, 4;
    add.s64 %rd12, %rd4, %rd11;
    st.global.f32 [%rd12], %fAcc;
EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, int):
            kernel_size = (kernel_size, kernel_size)
        if isinstance(stride, int):
            stride = (stride, stride)
        if isinstance(padding, int):
            padding = (padding, padding)
        if isinstance(dilation, int):
            dilation = (dilation, dilation)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias_flag = bias

        assert in_channels % groups == 0 and out_channels % groups == 0, "in_channels and out_channels must be divisible by groups"
        kh, kw = kernel_size
        cout_per_g = out_channels // groups

        self.weight = nn.Parameter(torch.empty(in_channels, cout_per_g, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        # Initialize like nn.ConvTranspose2d
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            # Match PyTorch ConvTranspose2d bias init: bound = 1/sqrt(fan_in)
            fan_in = (out_channels // groups) * kh * kw
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        N, Cin, H, W = x.shape
        kh, kw = self.kernel_size
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        G = self.groups
        Cout = self.out_channels
        # Output sizes
        Ho = (H - 1) * sh - 2 * ph + dh * (kh - 1) + 1
        Wo = (W - 1) * sw - 2 * pw + dw * (kw - 1) + 1

        y = torch.empty((N, Cout, Ho, Wo), device=x.device, dtype=x.dtype)

        x_c = x.contiguous()
        w_c = self.weight.contiguous()
        # Provide a valid pointer for bias always; kernel uses has_bias flag to decide
        b_t = self.bias.contiguous() if self.bias is not None else y

        total = N * Cout * Ho * Wo
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "convtrans2d_kernel",
            grid=(int(grid_x), 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x_c,
                w_c,
                b_t,
                y,
                i32(N),
                i32(Cin),
                i32(Cout),
                i32(H),
                i32(W),
                i32(kh),
                i32(kw),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
                i32(G),
                i32(Ho),
                i32(Wo),
                i32(1 if self.bias is not None else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

